  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  risk_code text NOT NULL DEFAULT 'RSK-' || lpad(nextval('seq_risk')::text, 6, '0') UNIQUE,
  title text NOT NULL,
  description text,
  category text NOT NULL DEFAULT 'operational' CHECK (category IN ('strategic', 'operational', 'financial', 'compliance', 'technology', 'safety', 'reputational')),
