  impact integer NOT NULL DEFAULT 3 CHECK (impact BETWEEN 1 AND 5),
  score integer GENERATED ALWAYS AS (likelihood * impact) STORED NOT NULL,
  rating text GENERATED ALWAYS AS (CASE WHEN likelihood * impact >= 15 THEN 'critical' WHEN likelihood * impact >= 10 THEN 'high' WHEN likelihood * impact >= 5 THEN 'medium' ELSE 'low' END) STORED NOT NULL,
  residual_likelihood integer CHECK (residual_likelihood BETWEEN 1 AND 5),
  residual_impact integer CHECK (residual_impact BETWEEN 1 AND 5),
  residual_score integer GENERATED ALWAYS AS (residual_likelihood * residual_impact) STORED,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'mitigating', 'accepted', 'transferred', 'closed')),
  treatment text CHECK (treatment IN ('mitigate', 'accept', 'transfer', 'avoid')),
  mitigation_plan text,
  review_date date,
  identified_on date NOT NULL DEFAULT current_date,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
