  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  control_id uuid NOT NULL REFERENCES grc_controls(id) ON DELETE CASCADE,
  tested_on date NOT NULL DEFAULT current_date,
  tested_by uuid REFERENCES users(id) ON DELETE SET NULL,
  result text NOT NULL CHECK (result IN ('effective', 'partially_effective', 'ineffective')),
  notes text,
  evidence_url text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_grc_control_tests_control_id ON grc_control_tests(control_id);
CREATE INDEX IF NOT EXISTS idx_grc_control_tests_tested_by ON grc_control_tests(tested_by);
DROP TRIGGER IF EXISTS trg_grc_control_tests_updated ON grc_control_tests;
CREATE TRIGGER trg_grc_control_tests_updated BEFORE UPDATE ON grc_control_tests FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS grc_risk_controls (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  risk_id uuid NOT NULL REFERENCES grc_risks(id) ON DELETE CASCADE,
  control_id uuid NOT NULL REFERENCES grc_controls(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (risk_id, control_id)
);
CREATE INDEX IF NOT EXISTS idx_grc_risk_controls_risk_id ON grc_risk_controls(risk_id);
CREATE INDEX IF NOT EXISTS idx_grc_risk_controls_control_id ON grc_risk_controls(control_id);
DROP TRIGGER IF EXISTS trg_grc_risk_controls_updated ON grc_risk_controls;
CREATE TRIGGER trg_grc_risk_controls_updated BEFORE UPDATE ON grc_risk_controls FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS grc_compliance_requirements (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  framework text NOT NULL,
  reference text NOT NULL,
  title text NOT NULL,
  description text,
  area text NOT NULL DEFAULT 'general' CHECK (area IN ('general', 'quality', 'environmental', 'health_safety', 'information_security', 'financial', 'privacy')),
  owner_id uuid REFERENCES users(id) ON DELETE SET NULL,
  control_id uuid REFERENCES grc_controls(id) ON DELETE SET NULL,
  status text NOT NULL DEFAULT 'not_assessed' CHECK (status IN ('not_assessed', 'compliant', 'partially_compliant', 'non_compliant', 'not_applicable')),
  last_assessed_on date,
  next_review_on date,
  evidence_url text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (framework, reference)
);
CREATE INDEX IF NOT EXISTS idx_grc_compliance_requirements_owner_id ON grc_compliance_requirements(owner_id);
CREATE INDEX IF NOT EXISTS idx_grc_compliance_requirements_control_id ON grc_compliance_requirements(control_id);
CREATE INDEX IF NOT EXISTS idx_grc_compliance_requirements_status ON grc_compliance_requirements(status);
DROP TRIGGER IF EXISTS trg_grc_compliance_requirements_updated ON grc_compliance_requirements;
CREATE TRIGGER trg_grc_compliance_requirements_updated BEFORE UPDATE ON grc_compliance_requirements FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS grc_audits (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  audit_code text NOT NULL DEFAULT 'AUD-' || lpad(nextval('seq_audit')::text, 6, '0') UNIQUE,
  title text NOT NULL,
  audit_type text NOT NULL DEFAULT 'internal' CHECK (audit_type IN ('internal', 'external', 'regulatory', 'supplier')),
  scope text,
  status text NOT NULL DEFAULT 'planned' CHECK (status IN ('planned', 'in_progress', 'reporting', 'completed', 'cancelled')),
  lead_auditor_id uuid REFERENCES users(id) ON DELETE SET NULL,
  planned_start date,
  planned_end date,
  actual_start date,
  actual_end date,
  summary text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_grc_audits_status ON grc_audits(status);
CREATE INDEX IF NOT EXISTS idx_grc_audits_lead_auditor_id ON grc_audits(lead_auditor_id);
DROP TRIGGER IF EXISTS trg_grc_audits_updated ON grc_audits;
CREATE TRIGGER trg_grc_audits_updated BEFORE UPDATE ON grc_audits FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS grc_audit_findings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  audit_id uuid NOT NULL REFERENCES grc_audits(id) ON DELETE CASCADE,
  title text NOT NULL,
  description text,
  severity text NOT NULL DEFAULT 'minor' CHECK (severity IN ('observation', 'minor', 'major', 'critical')),
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'in_remediation', 'verified', 'closed')),
  control_id uuid REFERENCES grc_controls(id) ON DELETE SET NULL,
  requirement_id uuid REFERENCES grc_compliance_requirements(id) ON DELETE SET NULL,
  owner_id uuid REFERENCES users(id) ON DELETE SET NULL,
  due_date date,
  closed_at timestamptz,
  remediation_plan text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_grc_audit_findings_audit_id ON grc_audit_findings(audit_id);
CREATE INDEX IF NOT EXISTS idx_grc_audit_findings_status ON grc_audit_findings(status);
CREATE INDEX IF NOT EXISTS idx_grc_audit_findings_control_id ON grc_audit_findings(control_id);
CREATE INDEX IF NOT EXISTS idx_grc_audit_findings_requirement_id ON grc_audit_findings(requirement_id);
CREATE INDEX IF NOT EXISTS idx_grc_audit_findings_owner_id ON grc_audit_findings(owner_id);
DROP TRIGGER IF EXISTS trg_grc_audit_findings_updated ON grc_audit_findings;
CREATE TRIGGER trg_grc_audit_findings_updated BEFORE UPDATE ON grc_audit_findings FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS am_assets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_tag text NOT NULL UNIQUE,
  name text NOT NULL,
  description text,
  category text,
  manufacturer text,
  model_name text,
  serial_number text,
  location text,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('planned', 'active', 'under_maintenance', 'idle', 'retired', 'disposed')),
  criticality text NOT NULL DEFAULT 'medium' CHECK (criticality IN ('low', 'medium', 'high', 'critical')),
  purchase_date date,
  purchase_cost numeric(18,2) NOT NULL DEFAULT 0,
  salvage_value numeric(18,2) NOT NULL DEFAULT 0,
  useful_life_months integer NOT NULL DEFAULT 60 CHECK (useful_life_months > 0),
  installed_on date,
  warranty_expires date,
  retired_on date,
  parent_asset_id uuid REFERENCES am_assets(id) ON DELETE SET NULL,
  assigned_to uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_am_assets_status ON am_assets(status);
CREATE INDEX IF NOT EXISTS idx_am_assets_parent_asset_id ON am_assets(parent_asset_id);
CREATE INDEX IF NOT EXISTS idx_am_assets_assigned_to ON am_assets(assigned_to);
DROP TRIGGER IF EXISTS trg_am_assets_updated ON am_assets;
CREATE TRIGGER trg_am_assets_updated BEFORE UPDATE ON am_assets FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS am_maintenance_plans (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_id uuid NOT NULL REFERENCES am_assets(id) ON DELETE CASCADE,
  name text NOT NULL,
  plan_type text NOT NULL DEFAULT 'preventive' CHECK (plan_type IN ('preventive', 'predictive', 'inspection', 'calibration')),
  frequency_days integer NOT NULL CHECK (frequency_days > 0),
  last_performed date,
  next_due date,
  estimated_hours numeric(18,2) NOT NULL DEFAULT 0,
  instructions text,
  assigned_to uuid REFERENCES users(id) ON DELETE SET NULL,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_am_maintenance_plans_asset_id ON am_maintenance_plans(asset_id);
CREATE INDEX IF NOT EXISTS idx_am_maintenance_plans_assigned_to ON am_maintenance_plans(assigned_to);
DROP TRIGGER IF EXISTS trg_am_maintenance_plans_updated ON am_maintenance_plans;
CREATE TRIGGER trg_am_maintenance_plans_updated BEFORE UPDATE ON am_maintenance_plans FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS am_work_orders (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  wo_number text NOT NULL DEFAULT 'WO-' || lpad(nextval('seq_wo')::text, 6, '0') UNIQUE,
  asset_id uuid NOT NULL REFERENCES am_assets(id) ON DELETE CASCADE,
  plan_id uuid REFERENCES am_maintenance_plans(id) ON DELETE SET NULL,
  title text NOT NULL,
  description text,
  wo_type text NOT NULL DEFAULT 'corrective' CHECK (wo_type IN ('preventive', 'corrective', 'predictive', 'inspection', 'calibration')),
  priority text NOT NULL DEFAULT 'medium' CHECK (priority IN ('low', 'medium', 'high', 'critical')),
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'scheduled', 'in_progress', 'on_hold', 'completed', 'cancelled')),
  scheduled_date date,
  started_at timestamptz,
  completed_at timestamptz,
  assigned_to uuid REFERENCES users(id) ON DELETE SET NULL,
  labor_hours numeric(18,2) NOT NULL DEFAULT 0,
  labor_cost numeric(18,2) NOT NULL DEFAULT 0,
  parts_cost numeric(18,2) NOT NULL DEFAULT 0,
  downtime_hours numeric(18,2) NOT NULL DEFAULT 0,
  failure_code text,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_am_work_orders_asset_id ON am_work_orders(asset_id);
CREATE INDEX IF NOT EXISTS idx_am_work_orders_plan_id ON am_work_orders(plan_id);
CREATE INDEX IF NOT EXISTS idx_am_work_orders_status ON am_work_orders(status);
CREATE INDEX IF NOT EXISTS idx_am_work_orders_assigned_to ON am_work_orders(assigned_to);
DROP TRIGGER IF EXISTS trg_am_work_orders_updated ON am_work_orders;
CREATE TRIGGER trg_am_work_orders_updated BEFORE UPDATE ON am_work_orders FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS am_meter_readings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_id uuid NOT NULL REFERENCES am_assets(id) ON DELETE CASCADE,
  metric text NOT NULL,
  value double precision NOT NULL,
  unit text,
  recorded_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_am_meter_readings_asset_id ON am_meter_readings(asset_id);
DROP TRIGGER IF EXISTS trg_am_meter_readings_updated ON am_meter_readings;
CREATE TRIGGER trg_am_meter_readings_updated BEFORE UPDATE ON am_meter_readings FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS am_predictive_alerts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_id uuid NOT NULL REFERENCES am_assets(id) ON DELETE CASCADE,
  metric text NOT NULL,
  severity text NOT NULL CHECK (severity IN ('warning', 'critical')),
  kind text NOT NULL DEFAULT 'anomaly' CHECK (kind IN ('anomaly', 'trend')),
  message text,
  observed_value double precision,
  expected_value double precision,
  z_score double precision,
  days_to_threshold double precision,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'acknowledged', 'resolved')),
  work_order_id uuid REFERENCES am_work_orders(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_am_predictive_alerts_asset_id ON am_predictive_alerts(asset_id);
CREATE INDEX IF NOT EXISTS idx_am_predictive_alerts_status ON am_predictive_alerts(status);
CREATE INDEX IF NOT EXISTS idx_am_predictive_alerts_work_order_id ON am_predictive_alerts(work_order_id);
DROP TRIGGER IF EXISTS trg_am_predictive_alerts_updated ON am_predictive_alerts;
CREATE TRIGGER trg_am_predictive_alerts_updated BEFORE UPDATE ON am_predictive_alerts FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS am_lifecycle_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_id uuid NOT NULL REFERENCES am_assets(id) ON DELETE CASCADE,
  event_type text NOT NULL CHECK (event_type IN ('acquired', 'commissioned', 'transferred', 'upgraded', 'repaired', 'revalued', 'retired', 'disposed')),
  event_date date NOT NULL DEFAULT current_date,
  description text,
  cost numeric(18,2),
  performed_by uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_am_lifecycle_events_asset_id ON am_lifecycle_events(asset_id);
CREATE INDEX IF NOT EXISTS idx_am_lifecycle_events_performed_by ON am_lifecycle_events(performed_by);
DROP TRIGGER IF EXISTS trg_am_lifecycle_events_updated ON am_lifecycle_events;
CREATE TRIGGER trg_am_lifecycle_events_updated BEFORE UPDATE ON am_lifecycle_events FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS ehs_incidents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  incident_number text NOT NULL DEFAULT 'INC-' || lpad(nextval('seq_incident')::text, 6, '0') UNIQUE,
  incident_type text NOT NULL CHECK (incident_type IN ('injury', 'illness', 'near_miss', 'property_damage', 'environmental_release', 'vehicle', 'security', 'other')),
  severity text NOT NULL DEFAULT 'minor' CHECK (severity IN ('minor', 'moderate', 'serious', 'critical', 'fatal')),
  title text NOT NULL,
  description text,
  occurred_at timestamptz NOT NULL,
  location text,
  reported_by uuid REFERENCES users(id) ON DELETE SET NULL,
  injured_person text,
  body_part text,
  lost_days integer NOT NULL DEFAULT 0,
  restricted_days integer NOT NULL DEFAULT 0,
  is_recordable boolean NOT NULL DEFAULT false,
  is_reportable boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'reported' CHECK (status IN ('reported', 'investigating', 'corrective_action', 'closed')),
  root_cause text,
  immediate_action text,
  asset_id uuid REFERENCES am_assets(id) ON DELETE SET NULL,
  closed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_ehs_incidents_reported_by ON ehs_incidents(reported_by);
CREATE INDEX IF NOT EXISTS idx_ehs_incidents_status ON ehs_incidents(status);
CREATE INDEX IF NOT EXISTS idx_ehs_incidents_asset_id ON ehs_incidents(asset_id);
DROP TRIGGER IF EXISTS trg_ehs_incidents_updated ON ehs_incidents;
CREATE TRIGGER trg_ehs_incidents_updated BEFORE UPDATE ON ehs_incidents FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS ehs_safety_audits (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  audit_number text NOT NULL DEFAULT 'SA-' || lpad(nextval('seq_safety_audit')::text, 6, '0') UNIQUE,
  title text NOT NULL,
  inspection_type text NOT NULL DEFAULT 'routine' CHECK (inspection_type IN ('routine', 'regulatory', 'contractor', 'pre_task')),
  location text,
  auditor_id uuid REFERENCES users(id) ON DELETE SET NULL,
  conducted_on date NOT NULL DEFAULT current_date,
  status text NOT NULL DEFAULT 'planned' CHECK (status IN ('planned', 'in_progress', 'completed')),
  score double precision,
  summary text,
  next_due date,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_ehs_safety_audits_auditor_id ON ehs_safety_audits(auditor_id);
CREATE INDEX IF NOT EXISTS idx_ehs_safety_audits_status ON ehs_safety_audits(status);
DROP TRIGGER IF EXISTS trg_ehs_safety_audits_updated ON ehs_safety_audits;
CREATE TRIGGER trg_ehs_safety_audits_updated BEFORE UPDATE ON ehs_safety_audits FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS ehs_safety_audit_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  audit_id uuid NOT NULL REFERENCES ehs_safety_audits(id) ON DELETE CASCADE,
  category text,
  item text NOT NULL,
  result text NOT NULL DEFAULT 'pending' CHECK (result IN ('pending', 'conforming', 'non_conforming', 'not_applicable')),
  comments text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_ehs_safety_audit_items_audit_id ON ehs_safety_audit_items(audit_id);
DROP TRIGGER IF EXISTS trg_ehs_safety_audit_items_updated ON ehs_safety_audit_items;
CREATE TRIGGER trg_ehs_safety_audit_items_updated BEFORE UPDATE ON ehs_safety_audit_items FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS ehs_environmental_readings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  site text NOT NULL,
  metric text NOT NULL,
  value double precision NOT NULL,
  unit text NOT NULL,
  reading_date date NOT NULL DEFAULT current_date,
  limit_value double precision,
  source text,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
DROP TRIGGER IF EXISTS trg_ehs_environmental_readings_updated ON ehs_environmental_readings;
CREATE TRIGGER trg_ehs_environmental_readings_updated BEFORE UPDATE ON ehs_environmental_readings FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS ehs_work_hours (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  site text,
  period_start date NOT NULL,
  period_end date NOT NULL,
  hours_worked numeric(18,2) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (period_end >= period_start)
);
DROP TRIGGER IF EXISTS trg_ehs_work_hours_updated ON ehs_work_hours;
CREATE TRIGGER trg_ehs_work_hours_updated BEFORE UPDATE ON ehs_work_hours FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS qms_test_plans (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  plan_code text NOT NULL DEFAULT 'TP-' || lpad(nextval('seq_test_plan')::text, 6, '0') UNIQUE,
  name text NOT NULL,
  description text,
  product text,
  characteristic text,
  method text,
  unit text,
  lower_limit double precision,
  upper_limit double precision,
  frequency text,
  acceptance_criteria text,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
DROP TRIGGER IF EXISTS trg_qms_test_plans_updated ON qms_test_plans;
CREATE TRIGGER trg_qms_test_plans_updated BEFORE UPDATE ON qms_test_plans FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS qms_test_results (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  test_plan_id uuid NOT NULL REFERENCES qms_test_plans(id) ON DELETE CASCADE,
  lot_number text,
  sample_id text,
  measured_value double precision,
  result text NOT NULL DEFAULT 'pending' CHECK (result IN ('pending', 'pass', 'fail')),
  tested_by uuid REFERENCES users(id) ON DELETE SET NULL,
  tested_at timestamptz NOT NULL DEFAULT now(),
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_qms_test_results_test_plan_id ON qms_test_results(test_plan_id);
CREATE INDEX IF NOT EXISTS idx_qms_test_results_tested_by ON qms_test_results(tested_by);
DROP TRIGGER IF EXISTS trg_qms_test_results_updated ON qms_test_results;
CREATE TRIGGER trg_qms_test_results_updated BEFORE UPDATE ON qms_test_results FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS qms_nonconformances (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ncr_number text NOT NULL DEFAULT 'NCR-' || lpad(nextval('seq_ncr')::text, 6, '0') UNIQUE,
  title text NOT NULL,
  description text,
  source text NOT NULL DEFAULT 'internal' CHECK (source IN ('internal', 'test', 'customer', 'supplier', 'audit')),
  severity text NOT NULL DEFAULT 'minor' CHECK (severity IN ('minor', 'major', 'critical')),
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'investigating', 'containment', 'corrective_action', 'verification', 'closed')),
  detected_on date NOT NULL DEFAULT current_date,
  detected_by uuid REFERENCES users(id) ON DELETE SET NULL,
  product_or_process text,
  lot_number text,
  test_result_id uuid REFERENCES qms_test_results(id) ON DELETE SET NULL,
  audit_finding_id uuid REFERENCES grc_audit_findings(id) ON DELETE SET NULL,
  quantity_affected integer,
  root_cause text,
  disposition text CHECK (disposition IN ('use_as_is', 'rework', 'repair', 'scrap', 'return_to_supplier')),
  closed_at timestamptz,
  owner_id uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_qms_nonconformances_status ON qms_nonconformances(status);
CREATE INDEX IF NOT EXISTS idx_qms_nonconformances_detected_by ON qms_nonconformances(detected_by);
CREATE INDEX IF NOT EXISTS idx_qms_nonconformances_test_result_id ON qms_nonconformances(test_result_id);
CREATE INDEX IF NOT EXISTS idx_qms_nonconformances_audit_finding_id ON qms_nonconformances(audit_finding_id);
CREATE INDEX IF NOT EXISTS idx_qms_nonconformances_owner_id ON qms_nonconformances(owner_id);
DROP TRIGGER IF EXISTS trg_qms_nonconformances_updated ON qms_nonconformances;
CREATE TRIGGER trg_qms_nonconformances_updated BEFORE UPDATE ON qms_nonconformances FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS qms_corrective_actions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  capa_number text NOT NULL DEFAULT 'CAPA-' || lpad(nextval('seq_capa')::text, 6, '0') UNIQUE,
  nonconformance_id uuid REFERENCES qms_nonconformances(id) ON DELETE SET NULL,
  incident_id uuid REFERENCES ehs_incidents(id) ON DELETE SET NULL,
  finding_id uuid REFERENCES grc_audit_findings(id) ON DELETE SET NULL,
  action_type text NOT NULL DEFAULT 'corrective' CHECK (action_type IN ('containment', 'corrective', 'preventive')),
  description text NOT NULL,
  owner_id uuid REFERENCES users(id) ON DELETE SET NULL,
  due_date date,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'in_progress', 'implemented', 'verified', 'closed', 'cancelled')),
  completed_on date,
  verified_by uuid REFERENCES users(id) ON DELETE SET NULL,
  verified_on date,
  effectiveness_check text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_qms_corrective_actions_nonconformance_id ON qms_corrective_actions(nonconformance_id);
CREATE INDEX IF NOT EXISTS idx_qms_corrective_actions_incident_id ON qms_corrective_actions(incident_id);
CREATE INDEX IF NOT EXISTS idx_qms_corrective_actions_finding_id ON qms_corrective_actions(finding_id);
CREATE INDEX IF NOT EXISTS idx_qms_corrective_actions_owner_id ON qms_corrective_actions(owner_id);
CREATE INDEX IF NOT EXISTS idx_qms_corrective_actions_status ON qms_corrective_actions(status);
CREATE INDEX IF NOT EXISTS idx_qms_corrective_actions_verified_by ON qms_corrective_actions(verified_by);
DROP TRIGGER IF EXISTS trg_qms_corrective_actions_updated ON qms_corrective_actions;
CREATE TRIGGER trg_qms_corrective_actions_updated BEFORE UPDATE ON qms_corrective_actions FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS doc_folders (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  parent_id uuid REFERENCES doc_folders(id) ON DELETE SET NULL,
  description text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_doc_folders_parent_id ON doc_folders(parent_id);
DROP TRIGGER IF EXISTS trg_doc_folders_updated ON doc_folders;
CREATE TRIGGER trg_doc_folders_updated BEFORE UPDATE ON doc_folders FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS doc_retention_policies (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL UNIQUE,
  description text,
  retention_years integer NOT NULL CHECK (retention_years >= 0),
  disposition_action text NOT NULL DEFAULT 'destroy' CHECK (disposition_action IN ('destroy', 'archive', 'review')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
DROP TRIGGER IF EXISTS trg_doc_retention_policies_updated ON doc_retention_policies;
CREATE TRIGGER trg_doc_retention_policies_updated BEFORE UPDATE ON doc_retention_policies FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS doc_documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  doc_number text NOT NULL DEFAULT 'DOC-' || lpad(nextval('seq_doc')::text, 6, '0') UNIQUE,
  title text NOT NULL,
  description text,
  doc_type text NOT NULL DEFAULT 'general' CHECK (doc_type IN ('policy', 'procedure', 'work_instruction', 'form', 'record', 'contract', 'report', 'drawing', 'general')),
  folder_id uuid REFERENCES doc_folders(id) ON DELETE SET NULL,
  owner_id uuid REFERENCES users(id) ON DELETE SET NULL,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'in_review', 'approved', 'effective', 'obsolete', 'archived')),
  confidentiality text NOT NULL DEFAULT 'internal' CHECK (confidentiality IN ('public', 'internal', 'confidential', 'restricted')),
  current_version integer NOT NULL DEFAULT 0,
  tags jsonb NOT NULL DEFAULT '[]'::jsonb,
  retention_policy_id uuid REFERENCES doc_retention_policies(id) ON DELETE SET NULL,
  is_record boolean NOT NULL DEFAULT false,
  legal_hold boolean NOT NULL DEFAULT false,
  effective_date date,
  review_due date,
  disposed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_doc_documents_folder_id ON doc_documents(folder_id);
CREATE INDEX IF NOT EXISTS idx_doc_documents_owner_id ON doc_documents(owner_id);
CREATE INDEX IF NOT EXISTS idx_doc_documents_status ON doc_documents(status);
CREATE INDEX IF NOT EXISTS idx_doc_documents_retention_policy_id ON doc_documents(retention_policy_id);
DROP TRIGGER IF EXISTS trg_doc_documents_updated ON doc_documents;
CREATE TRIGGER trg_doc_documents_updated BEFORE UPDATE ON doc_documents FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS doc_versions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  document_id uuid NOT NULL REFERENCES doc_documents(id) ON DELETE CASCADE,
  version_number integer NOT NULL,
  change_summary text,
  file_name text,
  mime_type text,
  size_bytes bigint,
  content_hash text,
  content_text text,
  storage_uri text,
  created_by uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (document_id, version_number)
);
CREATE INDEX IF NOT EXISTS idx_doc_versions_document_id ON doc_versions(document_id);
CREATE INDEX IF NOT EXISTS idx_doc_versions_created_by ON doc_versions(created_by);
DROP TRIGGER IF EXISTS trg_doc_versions_updated ON doc_versions;
CREATE TRIGGER trg_doc_versions_updated BEFORE UPDATE ON doc_versions FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS doc_workflows (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL UNIQUE,
  doc_type text,
  description text,
  is_active boolean NOT NULL DEFAULT true,
  steps jsonb NOT NULL DEFAULT '[]'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
DROP TRIGGER IF EXISTS trg_doc_workflows_updated ON doc_workflows;
CREATE TRIGGER trg_doc_workflows_updated BEFORE UPDATE ON doc_workflows FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS doc_workflow_instances (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workflow_id uuid NOT NULL REFERENCES doc_workflows(id) ON DELETE RESTRICT,
  document_id uuid NOT NULL REFERENCES doc_documents(id) ON DELETE CASCADE,
  version_number integer,
  status text NOT NULL DEFAULT 'in_progress' CHECK (status IN ('in_progress', 'approved', 'rejected', 'cancelled')),
  current_step integer NOT NULL DEFAULT 1,
  started_by uuid REFERENCES users(id) ON DELETE SET NULL,
  completed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_doc_workflow_instances_workflow_id ON doc_workflow_instances(workflow_id);
CREATE INDEX IF NOT EXISTS idx_doc_workflow_instances_document_id ON doc_workflow_instances(document_id);
CREATE INDEX IF NOT EXISTS idx_doc_workflow_instances_status ON doc_workflow_instances(status);
CREATE INDEX IF NOT EXISTS idx_doc_workflow_instances_started_by ON doc_workflow_instances(started_by);
DROP TRIGGER IF EXISTS trg_doc_workflow_instances_updated ON doc_workflow_instances;
CREATE TRIGGER trg_doc_workflow_instances_updated BEFORE UPDATE ON doc_workflow_instances FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE IF NOT EXISTS doc_workflow_tasks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  instance_id uuid NOT NULL REFERENCES doc_workflow_instances(id) ON DELETE CASCADE,
  step_order integer NOT NULL,
  step_name text NOT NULL,
  assigned_role text,
  assignee_id uuid REFERENCES users(id) ON DELETE SET NULL,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'skipped')),
  decided_by uuid REFERENCES users(id) ON DELETE SET NULL,
  decided_at timestamptz,
  comments text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_doc_workflow_tasks_instance_id ON doc_workflow_tasks(instance_id);
CREATE INDEX IF NOT EXISTS idx_doc_workflow_tasks_assignee_id ON doc_workflow_tasks(assignee_id);
CREATE INDEX IF NOT EXISTS idx_doc_workflow_tasks_status ON doc_workflow_tasks(status);
CREATE INDEX IF NOT EXISTS idx_doc_workflow_tasks_decided_by ON doc_workflow_tasks(decided_by);
DROP TRIGGER IF EXISTS trg_doc_workflow_tasks_updated ON doc_workflow_tasks;
CREATE TRIGGER trg_doc_workflow_tasks_updated BEFORE UPDATE ON doc_workflow_tasks FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX IF NOT EXISTS idx_am_readings_series ON am_meter_readings(asset_id, metric, recorded_at DESC);
CREATE INDEX IF NOT EXISTS idx_ehs_env_metric ON ehs_environmental_readings(site, metric, reading_date);

-- =====================================================================
-- Business rules enforced in the database
-- =====================================================================

-- CRM: case SLA + lifecycle timestamps
CREATE OR REPLACE FUNCTION crm_case_defaults() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.sla_due_at IS NULL THEN
    NEW.sla_due_at := now() + CASE NEW.priority
      WHEN 'critical' THEN interval '4 hours' WHEN 'high' THEN interval '8 hours'
      WHEN 'medium' THEN interval '24 hours' ELSE interval '72 hours' END;
  END IF;
  IF NEW.status IN ('resolved', 'closed') THEN
    IF NEW.resolved_at IS NULL THEN NEW.resolved_at := now(); END IF;
  ELSE
    NEW.resolved_at := NULL;
  END IF;
  IF NEW.status <> 'open' AND NEW.first_response_at IS NULL THEN NEW.first_response_at := now(); END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_crm_cases_defaults ON crm_cases;
CREATE TRIGGER trg_crm_cases_defaults BEFORE INSERT OR UPDATE ON crm_cases
  FOR EACH ROW EXECUTE FUNCTION crm_case_defaults();

-- CRM: opportunity probability follows the stage unless set explicitly
CREATE OR REPLACE FUNCTION crm_opportunity_defaults() RETURNS trigger AS $$
DECLARE stage_prob integer;
BEGIN
  stage_prob := CASE NEW.stage WHEN 'prospecting' THEN 10 WHEN 'qualification' THEN 25 WHEN 'proposal' THEN 50
                WHEN 'negotiation' THEN 75 WHEN 'closed_won' THEN 100 ELSE 0 END;
  IF TG_OP = 'INSERT' THEN
    NEW.probability := COALESCE(NEW.probability, stage_prob);
  ELSIF NEW.stage IS DISTINCT FROM OLD.stage AND NEW.probability IS NOT DISTINCT FROM OLD.probability THEN
    NEW.probability := stage_prob;
  END IF;
  IF NEW.stage IN ('closed_won', 'closed_lost') THEN
    IF NEW.closed_at IS NULL THEN NEW.closed_at := now(); END IF;
    NEW.probability := stage_prob;
  ELSE
    NEW.closed_at := NULL;
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_crm_opportunities_defaults ON crm_opportunities;
CREATE TRIGGER trg_crm_opportunities_defaults BEFORE INSERT OR UPDATE ON crm_opportunities
  FOR EACH ROW EXECUTE FUNCTION crm_opportunity_defaults();

-- PM: snapshot rates onto time entries
CREATE OR REPLACE FUNCTION pm_time_entry_rates() RETURNS trigger AS $$
DECLARE v_cost numeric; v_bill numeric;
BEGIN
  IF NEW.cost_rate IS NULL OR NEW.bill_rate IS NULL THEN
    SELECT hourly_cost, hourly_bill_rate INTO v_cost, v_bill FROM pm_resources WHERE id = NEW.resource_id;
    NEW.cost_rate := COALESCE(NEW.cost_rate, v_cost);
    NEW.bill_rate := COALESCE(NEW.bill_rate, v_bill);
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_pm_time_entries_rates ON pm_time_entries;
CREATE TRIGGER trg_pm_time_entries_rates BEFORE INSERT ON pm_time_entries
  FOR EACH ROW EXECUTE FUNCTION pm_time_entry_rates();

-- PM: task status drives progress and actual dates
CREATE OR REPLACE FUNCTION pm_task_defaults() RETURNS trigger AS $$
BEGIN
  IF NEW.status = 'completed' THEN
    NEW.percent_complete := 100;
    IF NEW.actual_start IS NULL THEN NEW.actual_start := COALESCE(NEW.planned_start, current_date); END IF;
    IF NEW.actual_end IS NULL THEN NEW.actual_end := current_date; END IF;
  ELSIF NEW.status = 'in_progress' AND NEW.actual_start IS NULL THEN
    NEW.actual_start := current_date;
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_pm_tasks_defaults ON pm_tasks;
CREATE TRIGGER trg_pm_tasks_defaults BEFORE INSERT OR UPDATE ON pm_tasks
  FOR EACH ROW EXECUTE FUNCTION pm_task_defaults();

-- GRC: audit finding closure timestamp
CREATE OR REPLACE FUNCTION grc_finding_defaults() RETURNS trigger AS $$
BEGIN
  IF NEW.status = 'closed' THEN
    IF NEW.closed_at IS NULL THEN NEW.closed_at := now(); END IF;
  ELSE NEW.closed_at := NULL; END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_grc_findings_defaults ON grc_audit_findings;
CREATE TRIGGER trg_grc_findings_defaults BEFORE INSERT OR UPDATE ON grc_audit_findings
  FOR EACH ROW EXECUTE FUNCTION grc_finding_defaults();

-- Assets: maintenance plan next-due date
CREATE OR REPLACE FUNCTION am_plan_defaults() RETURNS trigger AS $$
BEGIN
  IF NEW.next_due IS NULL THEN
    NEW.next_due := COALESCE(NEW.last_performed, current_date) + NEW.frequency_days;
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_am_plans_defaults ON am_maintenance_plans;
CREATE TRIGGER trg_am_plans_defaults BEFORE INSERT OR UPDATE ON am_maintenance_plans
  FOR EACH ROW EXECUTE FUNCTION am_plan_defaults();

-- Assets: work order lifecycle timestamps
CREATE OR REPLACE FUNCTION am_wo_defaults() RETURNS trigger AS $$
BEGIN
  IF NEW.status = 'in_progress' AND NEW.started_at IS NULL THEN NEW.started_at := now(); END IF;
  IF NEW.status = 'completed' THEN
    IF NEW.started_at IS NULL THEN NEW.started_at := now(); END IF;
    IF NEW.completed_at IS NULL THEN NEW.completed_at := now(); END IF;
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_am_wo_defaults ON am_work_orders;
CREATE TRIGGER trg_am_wo_defaults BEFORE INSERT OR UPDATE ON am_work_orders
  FOR EACH ROW EXECUTE FUNCTION am_wo_defaults();

-- EHS: incident closure timestamp
CREATE OR REPLACE FUNCTION ehs_incident_defaults() RETURNS trigger AS $$
BEGIN
  IF NEW.status = 'closed' THEN
    IF NEW.closed_at IS NULL THEN NEW.closed_at := now(); END IF;
  ELSE NEW.closed_at := NULL; END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_ehs_incidents_defaults ON ehs_incidents;
CREATE TRIGGER trg_ehs_incidents_defaults BEFORE INSERT OR UPDATE ON ehs_incidents
  FOR EACH ROW EXECUTE FUNCTION ehs_incident_defaults();

-- QMS: evaluate test results against plan limits
CREATE OR REPLACE FUNCTION qms_test_result_eval() RETURNS trigger AS $$
DECLARE p qms_test_plans%ROWTYPE;
BEGIN
  IF NEW.result = 'pending' AND NEW.measured_value IS NOT NULL THEN
    SELECT * INTO p FROM qms_test_plans WHERE id = NEW.test_plan_id;
    IF p.lower_limit IS NOT NULL OR p.upper_limit IS NOT NULL THEN
      IF (p.lower_limit IS NOT NULL AND NEW.measured_value < p.lower_limit)
         OR (p.upper_limit IS NOT NULL AND NEW.measured_value > p.upper_limit) THEN
        NEW.result := 'fail';
      ELSE
        NEW.result := 'pass';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_qms_test_results_eval ON qms_test_results;
CREATE TRIGGER trg_qms_test_results_eval BEFORE INSERT OR UPDATE ON qms_test_results
  FOR EACH ROW EXECUTE FUNCTION qms_test_result_eval();

-- QMS: a failed test automatically raises a non-conformance
CREATE OR REPLACE FUNCTION qms_test_result_ncr() RETURNS trigger AS $$
DECLARE p_name text;
BEGIN
  IF NEW.result = 'fail' AND NOT EXISTS (SELECT 1 FROM qms_nonconformances WHERE test_result_id = NEW.id) THEN
    SELECT name INTO p_name FROM qms_test_plans WHERE id = NEW.test_plan_id;
    INSERT INTO qms_nonconformances (title, description, source, severity, lot_number, test_result_id, product_or_process)
    VALUES ('Failed test: ' || p_name,
            'Auto-raised from failed test result ' || NEW.id || COALESCE(' (measured value ' || NEW.measured_value::text || ')', ''),
            'test', 'minor', NEW.lot_number, NEW.id, p_name);
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_qms_test_results_ncr ON qms_test_results;
CREATE TRIGGER trg_qms_test_results_ncr AFTER INSERT OR UPDATE OF result ON qms_test_results
  FOR EACH ROW EXECUTE FUNCTION qms_test_result_ncr();

-- QMS: a non-conformance cannot be closed while corrective actions are open
CREATE OR REPLACE FUNCTION qms_ncr_guard() RETURNS trigger AS $$
BEGIN
  IF NEW.status = 'closed' THEN
    IF EXISTS (SELECT 1 FROM qms_corrective_actions
               WHERE nonconformance_id = NEW.id AND status NOT IN ('verified', 'closed', 'cancelled')) THEN
      RAISE EXCEPTION 'Cannot close nonconformance %: corrective actions are still open', NEW.ncr_number
        USING ERRCODE = '23514';
    END IF;
    IF NEW.closed_at IS NULL THEN NEW.closed_at := now(); END IF;
  ELSE
    NEW.closed_at := NULL;
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_qms_ncr_guard ON qms_nonconformances;
CREATE TRIGGER trg_qms_ncr_guard BEFORE INSERT OR UPDATE ON qms_nonconformances
  FOR EACH ROW EXECUTE FUNCTION qms_ncr_guard();

-- Documents: versions are immutable
CREATE OR REPLACE FUNCTION doc_version_immutable() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'Document versions are immutable' USING ERRCODE = '23514';
END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_doc_versions_immutable ON doc_versions;
CREATE TRIGGER trg_doc_versions_immutable BEFORE UPDATE ON doc_versions
  FOR EACH ROW EXECUTE FUNCTION doc_version_immutable();

-- Documents: records and legal holds cannot be deleted
CREATE OR REPLACE FUNCTION doc_delete_guard() RETURNS trigger AS $$
BEGIN
  IF OLD.legal_hold THEN
    RAISE EXCEPTION 'Document % is under legal hold and cannot be deleted', OLD.doc_number USING ERRCODE = '23514';
  END IF;
  IF OLD.is_record THEN
    RAISE EXCEPTION 'Document % is a controlled record; use the disposition process', OLD.doc_number USING ERRCODE = '23514';
  END IF;
  RETURN OLD;
END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_doc_delete_guard ON doc_documents;
CREATE TRIGGER trg_doc_delete_guard BEFORE DELETE ON doc_documents
  FOR EACH ROW EXECUTE FUNCTION doc_delete_guard();

